begin;set local lock_timeout='3s';set local statement_timeout='20s';
do $$begin if (select count(*) from auth.users where id in('78d81bd0-3381-499a-a8f3-f8264e36973c','1a368661-a2f6-49cb-9b82-e374c64d5382') and raw_user_meta_data->>'qa_physical_cache_canary'='554e817b-78b8-4e64-9a94-b2aa80fdca4d')<>2 then raise exception 'Physical canary identity guard failed';end if;end$$;
do $$begin if exists(select 1 from storage.objects where coalesce(owner_id,owner::text) in('78d81bd0-3381-499a-a8f3-f8264e36973c','1a368661-a2f6-49cb-9b82-e374c64d5382') or name like '78d81bd0-3381-499a-a8f3-f8264e36973c/%') or exists(select 1 from media_renditions.jobs j where j.source_owner in('78d81bd0-3381-499a-a8f3-f8264e36973c','1a368661-a2f6-49cb-9b82-e374c64d5382') and (j.state in('pending','processing','retry','ready') or exists(select 1 from media_renditions.attempts a where a.job_id=j.id and not a.cleanup_done))) or exists(select 1 from media_processing.jobs j where j.source_owner in('78d81bd0-3381-499a-a8f3-f8264e36973c','1a368661-a2f6-49cb-9b82-e374c64d5382') and (j.state in('pending','processing','retry','ready') or exists(select 1 from media_processing.attempts a where a.job_id=j.id and not a.cleanup_done))) then raise exception 'Physical canary media cleanup remains';end if;end$$;
delete from public.notifications where recipient_id in('78d81bd0-3381-499a-a8f3-f8264e36973c','1a368661-a2f6-49cb-9b82-e374c64d5382') or actor_id in('78d81bd0-3381-499a-a8f3-f8264e36973c','1a368661-a2f6-49cb-9b82-e374c64d5382');
delete from public.follows where follower_id='1a368661-a2f6-49cb-9b82-e374c64d5382' and following_id='78d81bd0-3381-499a-a8f3-f8264e36973c';
delete from auth.sessions where user_id in('78d81bd0-3381-499a-a8f3-f8264e36973c','1a368661-a2f6-49cb-9b82-e374c64d5382');
delete from public.profiles where id in('78d81bd0-3381-499a-a8f3-f8264e36973c','1a368661-a2f6-49cb-9b82-e374c64d5382');
delete from auth.identities where user_id in('78d81bd0-3381-499a-a8f3-f8264e36973c','1a368661-a2f6-49cb-9b82-e374c64d5382');
